#include <string.h>
#include <stdbool.h>

#define MAX_NODES 120005

int pref_trie[MAX_NODES][26];
int pref_nodes = 1;

int suff_trie[MAX_NODES][26];
int suff_nodes = 1;

void insert_pref(const char *s, int len) {
    int u = 1;
    for (int i = 0; i < len; i++) {
        int c = s[i] - 'a';
        if (!pref_trie[u][c]) {
            pref_trie[u][c] = ++pref_nodes;
        }
        u = pref_trie[u][c];
    }
}

void insert_suff(const char *s, int len) {
    int u = 1;
    for (int i = len - 1; i >= 0; i--) {
        int c = s[i] - 'a';
        if (!suff_trie[u][c]) {
            suff_trie[u][c] = ++suff_nodes;
        }
        u = suff_trie[u][c];
    }
}

bool check_pref(const char *s, int start, int len) {
    int u = 1;
    for (int i = 0; i < len; i++) {
        int c = s[start + i] - 'a';
        if (!pref_trie[u][c]) return false;
        u = pref_trie[u][c];
    }
    return true;
}

bool check_suff(const char *s, int len) {
    int u = 1;
    for (int i = len - 1; i >= 0; i--) {
        int c = s[i] - 'a';
        if (!suff_trie[u][c]) return false;
        u = suff_trie[u][c];
    }
    return true;
}

