    int n;
    if (scanf("%d", &n) != 1) return 0;

    static char s[32];
    for (int k = 1; k <= n; k++) {
        if (scanf("%s", s) != 1) break;
        int len = strlen(s);

        bool invalid = false;
        for (int L = 0; L <= len; L++) {
            bool cond1 = (L == 0) || check_suff(s, L);
            bool cond2 = (L == len) || check_pref(s, L, len - L);
            if (cond1 && cond2) {
                invalid = true;
                break;
            }
        }

        if (invalid) {
            printf("%s\n", s);
            return 0;
        }

        insert_pref(s, len);
        insert_suff(s, len);
    }

    printf("ok\n");
    return 0;
}
